from lxml import etree
from io import StringIO

from django.http import HttpResponse

def xpath_query(request):
    '''
    Get the `xpath` value from the GET request,
    get the 'xml' value from the GET request,
    construct and parse the xml payload,
    return the result of the XPath query "/tag[@id={}]" format from the parsed xml
    '''

    # Get values from GET request
    xpath_value = request.GET.get('xpath', None)
    xml_payload = request.GET.get('xml', None)

    if not xpath_value or not xml_payload:
        return HttpResponse("Invalid input", status=400)

    # Safe parsing of XML to prevent XXE attacks
    parser = etree.XMLParser(resolve_entities=False, no_network=True)
    try:
        xml_tree = etree.parse(StringIO(xml_payload), parser)
    except etree.XMLSyntaxError as e:
        return HttpResponse(f"Invalid XML: {str(e)}", status=400)

    # Construct safe XPath query
    xpath_expression = f"/tag[@id='{xpath_value}']"

    try:
        results = xml_tree.xpath(xpath_expression)
        result_text = etree.tostring(results[0], encoding='unicode') if results else "No match found"
    except etree.XPathEvalError as e:
        return HttpResponse(f"Invalid XPath expression: {str(e)}", status=400)

    return HttpResponse(result_text)
